import{_ as a,o as t,c as e,a2 as i}from"./chunks/framework.Di-jvWLj.js";const d=JSON.parse('{"title":"通用命令","description":"","frontmatter":{},"headers":[],"relativePath":"linux/Linux_commands.md","filePath":"linux/Linux_commands.md"}'),r={name:"linux/Linux_commands.md"};function l(o,p,n,s,m,c){return t(),e("div",null,[...p[0]||(p[0]=[i('<h1 id="通用命令" tabindex="-1">通用命令 <a class="header-anchor" href="#通用命令" aria-label="Permalink to &quot;通用命令&quot;">​</a></h1><p>cd 文件夹名</p><p>进入文件夹</p><p>cd ..</p><p>回到上一层，.. 即表示上一层目录/.表示当前目录，这可以在ll中看到</p><p>cd ~</p><p>回到home目录</p><p>ls</p><p>查看当前目录下有什么东西</p><p>ls -a</p><p>显示全部包括隐藏，如.git</p><p>ll(ls -l)</p><p>具体查看</p><p>tree</p><p>当前目录文件树状查看</p><p>cat 文件夹名</p><p>直接打印某文件内容</p><p>file 文件夹名</p><p>查看某文件性质</p><p>mv 路径A下的文件名 路径B</p><p>移动</p><p>一般需要提供很具体的路径 尤其是移动到与当前不相干的地方</p><p>举例</p><p>mv ~Downloads/bomb.tar ~/Desktop/mycode</p><p>mv 文件名字 文件新名字</p><p>改名</p><p>一次移动多个文件到一个地方</p><p>mv file1 file2 file3 ~/Desktop</p><p>cp</p><p>复制</p><p>man</p><p>手册</p><h3 id="vim" tabindex="-1">Vim <a class="header-anchor" href="#vim" aria-label="Permalink to &quot;Vim&quot;">​</a></h3><p>Vim 文件名</p><p>使用vim文本编辑器打开文件</p><p>i（insert）</p><p>出现insert可开始编辑</p><p>输入/搜索</p><p>得到第一个答案后先点enter</p><p>再点n看下一个 N看上一个</p><p>gg去top GG去bottom</p><p>ctrl D down 向下滚动半屏 ctrl U up 向上滚动半屏</p><p>ctrl F forward 向下滚动整屏 ctrl B backward 向上滚动整屏</p><p>ESC</p><p>退回到只读页面</p><p>:wq</p><p>保存并推出</p><p>:q!</p><p>不保存退出</p><h1 id="通用快捷键" tabindex="-1">通用快捷键 <a class="header-anchor" href="#通用快捷键" aria-label="Permalink to &quot;通用快捷键&quot;">​</a></h1><p>tab</p><p>一键补全</p><p>上下箭头</p><p>选择之前输入过的命令</p><p>Ctrl alt T</p><p>出terminal</p><p>Ctrl shift +</p><p>放大界面</p><p>ctrl shift c/v</p><p>复制粘贴</p><p>ctrl c</p><p>在命令行内为强制终止当前操作</p><p>ctrl l</p><p>刷新界面</p><p>Firefox about:config</p><p>放大</p><p>在一些不兼容上下箭头移动的窗口内，如tmux，可能可以使用：</p><p>ctrl B 【 来用上下键移动</p><h1 id="其他常用命令" tabindex="-1">其他常用命令 <a class="header-anchor" href="#其他常用命令" aria-label="Permalink to &quot;其他常用命令&quot;">​</a></h1><h3 id="安装外部文件" tabindex="-1">安装外部文件 <a class="header-anchor" href="#安装外部文件" aria-label="Permalink to &quot;安装外部文件&quot;">​</a></h3><p>通常可以使用</p><p>sudo apt install 文件名</p><p>sudo本身是以管理员身份运行</p><p>apt 下载器 依赖管理器 一键下载所有依赖库</p><p>install 安装</p><h3 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h3><p>git init -b main</p><p>-b的意思是--initial-branch，由于git默认初始分支是master，需要改为main，实际上git branch -m main也可以但这样就在初始化的时候一次性搞定了</p><p>git config user.name</p><p>git config user.email 这里一般不会使用真实email提交 可以使用github提供的映射email</p><p>形如 <a href="mailto:xxxxxxxxx+username@users.noreply.github.com" target="_blank" rel="noreferrer">xxxxxxxxx+username@users.noreply.github.com</a></p><p>git clone xxx.git</p><p>git remote add upstream xxx.git</p><p>添加某仓库为上游</p><p>git pull upstream master 获取新作业</p><p>git add . 将当前目录（.）下的所有发生变化的文件放进暂存区</p><p>git add -A 将仓库所有改动都放进暂存区，-A意为all，如果这个命令是在根目录敲，那和git add . 效果应当是一致的</p><p>git status 查看提交状态</p><p>git commit -m &quot;xxx&quot;</p><p>提交到本地仓库，-m是留言</p><p>这两步做完后依然在本地</p><p>git push -u origin main 第一次-u，意为--set-upstream，相当于记住，后面直接git push即可</p><p>推送到远程仓库</p><p>git log --oneline -x</p><p>看commit记录，最近几条</p><p>git ls-files</p><p>输出已被git跟踪的文件路径</p><h3 id="curl" tabindex="-1">Curl <a class="header-anchor" href="#curl" aria-label="Permalink to &quot;Curl&quot;">​</a></h3><p>下载</p><p>1、如何下载</p><p>curl -L</p><p>允许重定向的下载 常用于github等下载</p><p>2、下载后</p><p>-o output</p><p>自己命名</p><p>-O</p><p>用原来的名字</p><h3 id="解压缩" tabindex="-1">解压缩 <a class="header-anchor" href="#解压缩" aria-label="Permalink to &quot;解压缩&quot;">​</a></h3><p>tar -xvf bomb.tar</p><p>tar -zxvf bomb.tar.gz</p><p>unzip xxx.zip</p><h3 id="压缩" tabindex="-1">压缩 <a class="header-anchor" href="#压缩" aria-label="Permalink to &quot;压缩&quot;">​</a></h3><p>tar -zcvf</p><p>zip xxx.zip</p>',114)])])}const h=a(r,[["render",l]]);export{d as __pageData,h as default};
